import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const p=JSON.parse('{"title":"术语表","description":"","frontmatter":{"title":"术语表"},"headers":[],"relativePath":"a-share-investing-course/glossary.md","filePath":"a-share-investing-course/docs/glossary.md"}'),o={name:"a-share-investing-course/glossary.md"};function i(n,t,s,l,c,h){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>全书首教过的术语，按出场顺序的自然分组排列；一句话定义都是正文首现时用过的那句话。判据与剧本以各章正文为准，本表用于翻查。</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话定义</th></tr></thead><tbody><tr><td>股票</td><td>stock</td><td>一家公司所有权的一小份凭证，拿着它你就是这家公司的小股东。</td></tr><tr><td>A股</td><td>—</td><td>在中国大陆交易所（上交所、深交所、北交所）上市、以人民币交易的中国公司股票。</td></tr><tr><td>交易所</td><td>—</td><td>提供集中撮合买卖的官方市场，中国内地共三家：上交所、深交所、北交所。</td></tr><tr><td>指数</td><td>index</td><td>把一篮子股票的价格加权成一个数，用来看整体市场的冷热，如上证指数、沪深300。</td></tr><tr><td>多头</td><td>bull / long</td><td>认为价格会涨而买入的一方；买入力量。</td></tr><tr><td>空头</td><td>bear / short</td><td>认为价格会跌而卖出的一方；卖出力量。A股普通账户只能先买后卖，空头是持股的卖出方。</td></tr><tr><td>流动性</td><td>liquidity</td><td>想买时有人卖、想卖时有人买的容易程度；排队的人越多越容易成交。</td></tr><tr><td>盘口</td><td>—</td><td>买方五档出价与卖方五档要价的实时排队表，撮合发生的地方。</td></tr><tr><td>集合竞价</td><td>—</td><td>开盘前 9:15-9:25 集中收一轮买卖申报、按最大成交量原则定出开盘价的机制。</td></tr><tr><td>连续竞价</td><td>—</td><td>开盘后全天持续的逐笔撮合：价格优先、时间优先。</td></tr><tr><td>价格优先时间优先</td><td>—</td><td>撮合排队规则：出价更高的买单先成交、要价更低的卖单先成交；同价先到先得。</td></tr><tr><td>买一卖一</td><td>—</td><td>盘口上最接近成交的一档买价和卖价，两者之差叫价差。</td></tr><tr><td>T+1</td><td>—</td><td>A股规则：当天买入的股票最快下一个交易日才能卖；资金卖出当天可再用。</td></tr><tr><td>涨跌停</td><td>—</td><td>交易所给当天价格相对昨收盘划的硬边界，超出边报价申报无效；主板±10%（2026年7月起主板ST股同为±10%，此前为±5%）、创业板科创板±20%、北交所±30%。</td></tr><tr><td>ST股票</td><td>—</td><td>被交易所标注风险警示的股票（财务或规范出过问题），风险显著更高；2026年7月起主板ST涨跌幅与普通股一致为±10%，此前为±5%。</td></tr><tr><td>手</td><td>—</td><td>A股的买卖单位，1手=100股；买入必须以手的整数倍，卖出可以有零股。</td></tr><tr><td>印花税</td><td>—</td><td>卖出股票时交给国家的税，当前为成交金额的0.05%（买入不收）。</td></tr><tr><td>佣金</td><td>—</td><td>交给券商的手续费，买卖双向收取，常见万分之一到万分之三，通常单笔最低5元。</td></tr><tr><td>K线</td><td>candlestick</td><td>把一段时间内的开盘价、收盘价、最高价、最低价画成一根蜡烛状图形的价格记录。</td></tr><tr><td>开高低收</td><td>OHLC</td><td>一段时间内的开盘价、最高价、最低价、收盘价，一根K线的四个原始数据。</td></tr><tr><td>实体</td><td>body</td><td>K线中开盘价到收盘价的粗段，代表这段时间多空拉锯后的净结果。</td></tr><tr><td>影线</td><td>wick / shadow</td><td>K线实体上下伸出的细线，上影线摸过最高价、下影线探过最低价，记录盘中被反击回去的攻防。</td></tr><tr><td>阳线 / 阴线</td><td>—</td><td>收盘价高于开盘价的K线（A股软件默认画成红色）叫阳线；反之为阴线（默认绿色）。</td></tr><tr><td>分时图</td><td>—</td><td>把当天每分钟成交价连成一条线的图，是日K线背后那一天的『显微镜视图』。</td></tr><tr><td>周期聚合</td><td>—</td><td>把小周期K线合并成大周期：周K线的开=本周第一根日K的开、收=最后一根的收、高=最高的高、低=最低的低。</td></tr><tr><td>复权</td><td>—</td><td>把分红除权造成的价格跳空修补回连续序列的方法，看长期图必开前复权，否则形态全是假的。</td></tr><tr><td>大阳线 / 大阴线</td><td>—</td><td>实体特别长的阳线/阴线：一方从开盘压到收盘的全场大胜。</td></tr><tr><td>锤子线</td><td>hammer</td><td>长下影、小实体的单根K线：盘中被深砸但收盘收了回来，显示下方出现强承接。</td></tr><tr><td>上吊线</td><td>hanging man</td><td>形状与锤子线相同但出现在上涨之后：同样的图，位置不同，含义反转。</td></tr><tr><td>射击之星</td><td>shooting star</td><td>上涨后的长上影小实体K线：向上冲锋被当场打了回来，上方抛压的实弹测试。</td></tr><tr><td>倒锤子</td><td>inverted hammer</td><td>下跌后的长上影小实体：第一次认真试探上方抛压，收阳确认才有意义。</td></tr><tr><td>光头光脚</td><td>—</td><td>没有影线的K线：开盘即一路单边到收盘，一方全天压着打。</td></tr><tr><td>十字星</td><td>doji</td><td>开盘价≈收盘价、只剩影线的K线：多空打了一天打成平手，常是变盘前兆。</td></tr><tr><td>长腿十字</td><td>long-legged doji</td><td>上下影都特别长的十字星：巨大的分歧，两边都被推翻过一次。</td></tr><tr><td>蜻蜓线</td><td>dragonfly doji</td><td>开盘收盘都贴着最高点的长下影十字：全天砸下去又被全额买回。</td></tr><tr><td>墓碑线</td><td>gravestone doji</td><td>开盘收盘都贴着最低点的长上影十字：冲高的买盘全军覆没。</td></tr><tr><td>一字线</td><td>four-price doji</td><td>开=高=低=收四价合一：一字板，想买买不到、想卖卖不掉。</td></tr><tr><td>纺锤线</td><td>spinning top</td><td>实体影线都小的K线：多空都无意恋战，市场在打盹。</td></tr><tr><td>吞没形态</td><td>engulfing</td><td>今天的实体把昨天实体整个包住：今天的胜方不只是赢，还把昨天的战果整个收回。</td></tr><tr><td>乌云盖顶</td><td>dark cloud cover</td><td>上涨后高开却收在昨天实体中点之下的阴线：高开是最后的乐观，收不回去是反转信号。</td></tr><tr><td>刺透形态</td><td>piercing</td><td>下跌后低开却收进昨天阴线实体中点之上：恐慌盘被低位买盘正面顶回。</td></tr><tr><td>孕线</td><td>harami</td><td>今天的小实体整个缩在昨天大实体之内：攻势骤然踩了刹车，市场在犹豫。</td></tr><tr><td>十字孕线</td><td>doji harami</td><td>昨天大实体、今天十字星缩在其内：犹豫到极致，常是变盘前夜。</td></tr><tr><td>平顶 / 平底</td><td>tweezer top / bottom</td><td>两根K线的高点（低点）几乎落在同一价位：同一个位置两次证明有人守。</td></tr><tr><td>早晨之星</td><td>morning star</td><td>下跌末端『大阴+小实体星线+跳涨阳线』三根组合：卖压枯竭、买方接管的完整剧本。</td></tr><tr><td>黄昏之星</td><td>evening star</td><td>上涨末端『大阳+星线+跳跌阴线』：早晨之星的镜像，涨势熄火剧本。</td></tr><tr><td>红三兵 / 黑三鸦</td><td>—</td><td>连续三根温和递进的小阳线/小阴线：趋势按节奏推进，没有剧烈反扑。</td></tr><tr><td>红三兵受阻</td><td>—</td><td>红三兵之后紧跟高位小实体或长上影：推进撞上了墙的警示。</td></tr><tr><td>上升三法 / 下降三法</td><td>rising / falling three methods</td><td>趋势中继五根组合：一根大实体、三根缩在其影线范围内的小回撤、再一根同向大实体——歇脚不折返。</td></tr><tr><td>趋势</td><td>trend</td><td>价格留下的方向性足迹：更高的高点和更高的低点不断出现就是上升趋势。</td></tr><tr><td>道氏理论</td><td>Dow theory</td><td>查尔斯·道留下的趋势分析框架：趋势由波峰波谷的方向定义，且分主要/次级/日间三级。</td></tr><tr><td>趋势线 / 通道</td><td>—</td><td>连接回撤枢轴点的直线；把趋势线平移到对侧波峰得到通道的轨道。</td></tr><tr><td>均线</td><td>moving average, MA</td><td>最近N天收盘价的滑动平均，把噪声抹掉只留趋势的平滑线。</td></tr><tr><td>指数移动平均</td><td>EMA</td><td>给越新的价格越大权重的均线，对最新变化反应更快但仍滞后。</td></tr><tr><td>金叉 / 死叉</td><td>—</td><td>短期均线上穿/下穿长期均线：短期共识转向的迟到信号。</td></tr><tr><td>成交量</td><td>volume</td><td>一段时间内实际成交的股数，衡量参与度和分歧度：有人卖还得有人买才算成交。</td></tr><tr><td>换手率</td><td>—</td><td>成交量除以流通股本，今天有多少百分比的筹码换了主人。</td></tr><tr><td>量价背离</td><td>—</td><td>价格创新高/新低而成交量萎缩：推进的燃料不足，趋势可疑。</td></tr><tr><td>支撑 / 阻力</td><td>—</td><td>历史上买卖挂单反复扎堆的价格小区间：跌到有人接、涨到有人抛的位置。</td></tr><tr><td>枢轴点</td><td>pivot</td><td>局部的高点或低点拐角，画趋势线和支撑阻力的原材料。</td></tr><tr><td>假突破</td><td>false breakout</td><td>价格刺破支撑/阻力后又迅速收回：专门收割止损盘和追单的走势。</td></tr><tr><td>斐波那契回调</td><td>Fibonacci retracement</td><td>在一段涨跌幅上按0.236/0.382/0.5/0.618等比例画的潜在回撤刻度：信的人多了，刻度本身成了路口。</td></tr><tr><td>筹码分布</td><td>chip distribution / CYQ</td><td>估算每个价位上还压着多少持仓量的图：山峰=拥挤的历史成本区，获利盘/套牢盘比例由它算出。</td></tr><tr><td>头肩顶</td><td>head and shoulders</td><td>中间高点更高的三峰结构与颈线：涨势三次冲顶、两次回撤后买方接力枯竭的经典反转结构。</td></tr><tr><td>双顶 / 双底</td><td>double top / bottom</td><td>两次冲击同一价位失败形成的M顶/W底：同一个位置证明卖压/买压守得住。</td></tr><tr><td>颈线</td><td>neckline</td><td>头肩/双顶结构中连接回撤低点的参考线，跌破它才算结构成立。</td></tr><tr><td>缺口</td><td>gap</td><td>两根K线之间没有任何成交的价格真空区，常由隔夜消息或情绪跳空造成。</td></tr><tr><td>MACD</td><td>—</td><td>两条不同周期EMA的差值及其平滑线的组合指标，用来度量动量的方向与衰减。</td></tr><tr><td>背离</td><td>divergence</td><td>价格创新高/新低而指标拒绝跟随：推着价格走的燃料与价格本身唱反调。</td></tr><tr><td>RSI</td><td>relative strength index</td><td>最近一段上涨幅度占全部波动的百分比：衡量买方力量的持久度，而非超买超卖开关。</td></tr><tr><td>KDJ</td><td>stochastic oscillator</td><td>A股软件默认的摆动指标：收盘价在近期高低区间的位置（RSV）经两次平滑，对价格变化极敏感。</td></tr><tr><td>布林带</td><td>Bollinger bands</td><td>均线±若干倍标准差构成的三条带：用波动率而不是固定百分比画的弹性通道。</td></tr><tr><td>标准差</td><td>standard deviation</td><td>衡量一组数离平均数平均有多远的量，价格波动的『颠簸幅度』。</td></tr><tr><td>胜率</td><td>—</td><td>盈利交易次数占全部交易次数的比例，单独看没有意义，必须配盈亏比。</td></tr><tr><td>盈亏比</td><td>—</td><td>平均每笔盈利金额与平均每笔亏损金额之比。</td></tr><tr><td>期望值</td><td>expectancy</td><td>胜率×平均盈利−败率×平均亏损：长期平均每次交易的期望盈亏。</td></tr><tr><td>止损</td><td>stop loss</td><td>进场前就定好的认输价位：单次亏损的硬上限，让错误变得廉价。</td></tr><tr><td>仓位</td><td>position sizing</td><td>一笔交易投入的资金比例；决定错了多痛、对了多赚的旋钮。</td></tr><tr><td>凯利公式</td><td>Kelly criterion</td><td>按胜率与盈亏比算出的最优下注比例公式；实战取其分数，因为参数是估计值。</td></tr><tr><td>破产风险</td><td>risk of ruin</td><td>连续亏损把本金打到无法继续（或心态崩溃）的概率；仓位越重、盈亏比越差越高。</td></tr><tr><td>回测</td><td>backtest</td><td>用历史数据按规则彩排交易、统计成绩的实验方法。</td></tr><tr><td>未来函数</td><td>—</td><td>回测里用了当时不可能知道的数据（如用收盘价决定当天开盘买入）：偷看答案，胜率虚高。</td></tr><tr><td>过拟合</td><td>overfitting</td><td>把历史噪声当规律背下来：参数调到历史完美，遇到未来就碎。</td></tr><tr><td>幸存者偏差</td><td>survivorship bias</td><td>只用活到今天的样本做统计，退市股、爆雷股不在样本里，结论偏乐观。</td></tr><tr><td>最大回撤</td><td>max drawdown</td><td>账户从历史最高点到之后最低点的最大跌幅：最深那次下坡有多疼。</td></tr><tr><td>滑点</td><td>slippage</td><td>预期成交价与实际成交价的差，急市里按市价吃单要多付的成本。</td></tr><tr><td>市盈率</td><td>PE</td><td>股价÷每股盈利：按现在的利润，几年回本；衡量市场给公司多少倍溢价。</td></tr><tr><td>市净率</td><td>PB</td><td>股价÷每股净资产：价格是家底的几倍；银行等重资产行业常用。</td></tr><tr><td>ROE</td><td>—</td><td>净资产收益率：公司拿股东的钱一年能赚回百分之几，长期赚钱能力的核心指标。</td></tr><tr><td>处置效应</td><td>disposition effect</td><td>赚一点急着落袋、亏了死扛不认账的行为偏差：拔鲜花、浇野草。</td></tr><tr><td>交易系统</td><td>—</td><td>把入场、止损、仓位、离场写成可执行清单的完整规则集，作用是替你挡住盘中情绪。</td></tr></tbody></table>',3)])])}const m=d(o,[["render",i]]);export{p as __pageData,m as default};
